import type { ReactNode } from 'react';
import type { Metadata } from 'next';
import type { Portfolio, ThemePreference } from '@portfolio/schema';
import { THEME_INIT_SCRIPT, ThemeProvider } from '@portfolio/kit';
import { buildStructuredData } from '@portfolio/kit/seo';
import { manifest as editorialManifest } from '@portfolio/variant-editorial';
import { jsonLdScript } from '~/lib/json-ld';
import { getLive } from '~/server/catalog';
import { requireDeploymentConfig } from '~/server/config-store';
import './globals.css';
// Generated by `pnpm --filter @portfolio/web build:registry`.
// Side-effect imports every registered variant's styles.css so the host
// doesn't have to hard-code per-variant CSS imports.
import '~/lib/registry.styles.generated';

// Rendered per request from the revision register() loaded at startup, so a
// build with no deployment configuration (the image's) never bakes in a
// portfolio or an origin. That includes the 404 page.
export const dynamic = 'force-dynamic';

/**
 * The live portfolio, or null when the catalog can't produce one. Under
 * `next dev` an invalid edit lands here; the layout renders neutral defaults
 * and the page's own failure reaches app/error.tsx.
 */
async function livePortfolio(): Promise<Portfolio | null> {
  try {
    return (await getLive()).unit.portfolio;
  } catch {
    return null;
  }
}

export async function generateMetadata(): Promise<Metadata> {
  const { origin } = requireDeploymentConfig();
  const portfolio = await livePortfolio();
  if (!portfolio) return { title: 'Portfolio', metadataBase: new URL(origin) };

  const title = portfolio.meta?.title ?? `${portfolio.identity.name} — Portfolio`;
  const description = portfolio.meta?.description ?? portfolio.identity.tagline;
  return {
    title,
    description,
    authors: [{ name: portfolio.identity.name }],
    creator: portfolio.identity.name,
    metadataBase: new URL(origin),
    openGraph: {
      type: 'profile',
      title,
      description,
      siteName: title,
      url: '/',
    },
    twitter: {
      card: 'summary_large_image',
      title,
      description,
    },
  };
}

export default async function RootLayout({ children }: { children: ReactNode }) {
  const { origin } = requireDeploymentConfig();
  const portfolio = await livePortfolio();
  const defaultPreference: ThemePreference = portfolio?.theme ?? 'system';
  const jsonLdBlocks = portfolio
    ? buildStructuredData(portfolio, { siteUrl: origin }).map(jsonLdScript)
    : [];

  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: THEME_INIT_SCRIPT }} />
        {jsonLdBlocks.map((json, i) => (
          <script key={i} type="application/ld+json" dangerouslySetInnerHTML={{ __html: json }} />
        ))}
      </head>
      <body>
        <ThemeProvider
          defaultPreference={defaultPreference}
          supportedThemes={editorialManifest.themes}
        >
          {children}
        </ThemeProvider>
      </body>
    </html>
  );
}
